Lemma desc_flip_lemma (x y z : nat) :
  x <> y -> x <> z -> y <> z ->
  (y < z)%N = (x < z)%N -> (z < x)%N = (z < y)%N.
Proof.
move=> Hxy Hxz Hyz Hbc.
apply/idP/idP => H; apply/ltP; apply/ltP: H;
  move: Hbc; case Hxz' : (x < z)%N; case Hyz' : (y < z)%N;
    move: Hxz' Hyz' => /ltP ? /ltP ?; lia.
Qed.

